import { User } from '../../domain/user/User';
import { UserRepository } from '../../domain/user/UserRepository';
import { toUserDto, UserDto } from '../dto/UserDto';
import { IdGenerator } from '../ports/IdGenerator';
import { CreateUserInput, CreateUserUseCase } from './CreateUserUseCase';

export class CreateUserService implements CreateUserUseCase {
  constructor(
    private readonly users: UserRepository,
    private readonly ids: IdGenerator,
  ) {}

  async execute(input: CreateUserInput): Promise<UserDto> {
    const user = User.create(this.ids.next(), input.name);
    await this.users.save(user);
    return toUserDto(user);
  }
}

=====SOURCE-END=====

